package com.bank.flink.ij;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

// Models a Flink interval join: buffers orders, matches confirmations within
// a 4-hour window, and evicts orders once the watermark passes their window.
class IntervalJoinEngine {
    private static final Logger log = Logger.getLogger(IntervalJoinEngine.class.getName());
    private static final long FOUR_HOURS_MS = 4L * 60 * 60 * 1000;

    // order_id -> buffered order (keyed state on the left side)
    private final Map<String, Order> orderState = new ConcurrentHashMap<>();

    void onOrder(Order o) {
        orderState.put(o.getOrderId(), o);
        log.info(() -> "buffered order " + o.getOrderId() + " amount=" + o.getAmount());
    }

    // A confirmation arrives: match it to an order inside the interval.
    String onShipment(Shipment s) {
        Order o = orderState.get(s.getOrderId());
        if (o == null) {
            log.warning(() -> "no buffered order for confirmation " + s.getOrderId());
            return null;
        }
        long low = s.getShipTimeMillis() - FOUR_HOURS_MS;
        long high = s.getShipTimeMillis();
        if (o.getOrderTimeMillis() >= low && o.getOrderTimeMillis() <= high) {
            String joined = "JOINED order=" + o.getOrderId() + " account=" + o.getAccountId()
                    + " amount=" + o.getAmount() + " shipTime=" + s.getShipTimeMillis();
            log.info(() -> joined);
            return joined;
        }
        log.warning(() -> "order " + o.getOrderId() + " outside 4h interval; no match");
        return null;
    }

    // Watermark advance: drop orders that can no longer match any future confirmation.
    int onWatermark(long watermarkMillis) {
        Iterator<Map.Entry<String, Order>> it = orderState.entrySet().iterator();
        int evicted = 0;
        while (it.hasNext()) {
            Order o = it.next().getValue();
            // once watermark > orderTime + 4h, no confirmation can still match.
            if (watermarkMillis > o.getOrderTimeMillis() + FOUR_HOURS_MS) {
                it.remove();
                evicted++;
            }
        }
        int finalEvicted = evicted;
        log.fine(() -> "watermark=" + watermarkMillis + " evicted=" + finalEvicted
                + " stateSize=" + orderState.size());
        return finalEvicted;
    }

    int stateSize() { return orderState.size(); }

    List<String> bufferedOrderIds() { return new ArrayList<>(orderState.keySet()); }
}
