package com.bank.flink.ij;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class IntervalJoinDemo {
    private static final Logger log = Logger.getLogger(IntervalJoinDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        IntervalJoinEngine engine = new IntervalJoinEngine();
        long base = 0L;
        long hour = 60L * 60 * 1000;

        // Orders from Rajesh (SAV2001) and Priya (CUR3001).
        engine.onOrder(new Order("ORD-1", "SAV2001", new BigDecimal("50000"), base + 1 * hour));
        engine.onOrder(new Order("ORD-2", "CUR3001", new BigDecimal("12000"), base + 2 * hour));

        // Confirmation within 4h of ORD-1 -> matches.
        log.info("Result: " + engine.onShipment(new Shipment("ORD-1", base + 3 * hour)));

        // Confirmation for ORD-2 arrives 6h later -> outside interval, no match.
        log.info("Result: " + engine.onShipment(new Shipment("ORD-2", base + 8 * hour)));

        // Advance watermark to 6h: ORD-1 (orderTime 1h) can be evicted (1h+4h < 6h).
        log.info("Evicted at wm=6h: " + engine.onWatermark(base + 6 * hour));
        log.info("State now holds: " + engine.bufferedOrderIds());

        // Advance watermark to 9h: ORD-2 (orderTime 2h) now evictable too.
        log.info("Evicted at wm=9h: " + engine.onWatermark(base + 9 * hour));
        log.info("Final state size: " + engine.stateSize());
    }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
